/**
 * Generates supabase/seed.sql from data/starter-rules.json.
 *   pnpm seed:build
 * The JSON file is the source of truth; never hand-edit seed.sql.
 */
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { compileBundle, rowsFromSource, type RuleSource } from '../packages/rules-engine/src/index.ts';
import { lit, readStarter, ROOT } from './lib.ts';

export function buildSeedSql(src: RuleSource): string {
  // Validate first: the same checks the publish step runs.
  compileBundle(rowsFromSource(src));

  const out: string[] = [
    '-- GENERATED by scripts/build-seed.ts from data/starter-rules.json. Do not edit by hand.',
    '-- Starter rules are Mindset ingredient preferences, not safety findings.',
    'begin;',
    '',
  ];

  src.categories.forEach((c, i) => {
    out.push(
      `insert into public.categories (id, label, toggleable, sort_order) values (${lit(c.id)}, ${lit(c.label)}, ${c.toggleable}, ${i}) ` +
        `on conflict (id) do update set label = excluded.label, toggleable = excluded.toggleable, sort_order = excluded.sort_order;`,
    );
  });
  out.push('');

  for (const ing of src.ingredients) {
    const sources = JSON.stringify(ing.sources ?? { regulator: [], preference: [] });
    out.push(
      'insert into public.ingredients (id, display_name, short_name, category, tier, strict_tier, reason_short, reason_long, e_number, sources, is_active) values (' +
        [
          lit(ing.id),
          lit(ing.display_name),
          lit(ing.short_name ?? null),
          lit(ing.category),
          `${lit(ing.tier)}::public.tier`,
          `${lit(ing.strict_tier)}::public.tier`,
          lit(ing.reason_short ?? ''),
          lit(ing.reason_long ?? null),
          lit(ing.e_numbers?.[0] ?? null),
          `${lit(sources)}::jsonb`,
          'true',
        ].join(', ') +
        ') on conflict (id) do update set display_name = excluded.display_name, short_name = excluded.short_name, category = excluded.category, ' +
        'tier = excluded.tier, strict_tier = excluded.strict_tier, reason_short = excluded.reason_short, reason_long = excluded.reason_long, ' +
        'e_number = excluded.e_number, sources = excluded.sources, is_active = excluded.is_active;',
    );
  }
  out.push('');

  for (const ing of src.ingredients) {
    const rows = [
      ...ing.aliases.map((a) => `(${lit(a)}, ${lit(ing.id)}, 'en', 'name'::public.alias_kind)`),
      ...(ing.e_numbers ?? []).map((e) => `(${lit(e)}, ${lit(ing.id)}, 'en', 'e_number'::public.alias_kind)`),
    ];
    if (!rows.length) continue;
    // alias_norm is filled by the aliases_norm trigger; the placeholder satisfies NOT NULL.
    out.push(
      `insert into public.aliases (alias, alias_norm, ingredient_id, lang, kind) select v.alias, '', v.ingredient_id, v.lang, v.kind from (values\n  ${rows.join(',\n  ')}\n) as v(alias, ingredient_id, lang, kind)\n` +
        `on conflict (alias_norm) do nothing;`,
    );
  }

  out.push('', 'commit;', '');
  return out.join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const sql = buildSeedSql(readStarter());
  const path = resolve(ROOT, 'supabase/seed.sql');
  writeFileSync(path, sql);
  console.log(`Wrote ${path} (${sql.split('\n').length} lines)`);
}
